# B02: the daily cycle. App 9aba8d35, days 2-4, unscaled requests per minute, with a 61-minute average.
# --------------------------------------------------------------------------------------------
class B02_DailyCycle(Scene):
    BID, DEFAULT = "B02", 12.0

    def construct(self):
        self.begin()
        x = np.array(E["hero3_min"], dtype=float)
        hl = headline("Traffic rises and falls once a day", "Rises and falls", "once a day")
        credit, cite = credit_block(), cite_block()
        ylab = T("requests per minute", 28, SLATE)
        leg = VGroup(swatch(SLATE, "every minute"), swatch(GOLD, "hourly average"))
        if PORTRAIT:
            column([credit, cite, ylab], hl.get_bottom()[1] - 0.22, 0.58, left=-SX, min_gap=0.12)
            box = Box(-SX + 0.85, -1.5, SX - 0.05, ylab.get_bottom()[1] - 0.2, (0, 4320), (0, 1600))
            yt = [(0, "0"), (500, "500"), (1000, "1k"), (1500, "1.5k")]
            xt = []
            days = place(T("days 2, 3 and 4", 26, SLATE), x=(box.x0 + box.x1) / 2, top=box.y0 - 0.12)
            leg.arrange(DOWN, buff=0.08, aligned_edge=LEFT)
            place(leg, left=-SX, bottom=TEXT_FLOOR)
        else:
            place(credit, right=SX, y=hl[0].get_center()[1])
            place(ylab, left=-SX, top=hl.get_bottom()[1] - 0.25)
            place(cite, right=SX, y=ylab.get_center()[1])
            box = Box(-SX + 1.15, -2.2, SX - 0.05, ylab.get_bottom()[1] - 0.25, (0, 4320), (0, 1600))
            yt = [(0, "0"), (500, "500"), (1000, "1,000"), (1500, "1,500")]
            xt = [(720 + 1440 * d, f"day {d + 2}") for d in range(3)]
            days = VGroup()
            leg.arrange(RIGHT, buff=0.6)
            place(leg, left=-SX, bottom=-SY)
        ax = axes(box, yt, xt)
        seps = VGroup(*[DashedLine(box.p(1440 * d, 0), box.p(1440 * d, 1600), stroke_color=GREY, stroke_width=2,
                                   dash_length=0.06) for d in (1, 2)])
        raw = box.line(list(range(len(x))), x, SLATE, 2 if PORTRAIT else 2.5)
        avg = np.convolve(np.pad(x, 30, mode="edge"), np.ones(61) / 61, "valid")
        smooth = box.line(list(range(0, len(x), 10)), avg[::10], GOLD, 5 if PORTRAIT else 6)
        self.P(FadeIn(hl), FadeIn(credit), FadeIn(cite), FadeIn(ax), FadeIn(seps), FadeIn(ylab), FadeIn(days), rt=0.9)
        self.at(0.12)
        self.P(Create(raw, rate_func=linear), FadeIn(leg[0]), rt=0.42 * self.D)
        self.at(0.62)
        self.P(Create(smooth), FadeIn(leg[1]), rt=1.6)
        self.end()


