# B03: noise. App 38ee9fad, day 3, 14:00-15:00: 60 per-minute values around the trailing 30-minute
# median, with a band of plus or minus 15%.
# --------------------------------------------------------------------------------------------
class B03_Noise(Scene):
    BID, DEFAULT = "B03", 11.0

    def construct(self):
        self.begin()
        nh = E["noise_hour"]
        load, med = np.array(nh["load"], float), np.array(nh["median"], float)
        hl = headline("One hour: never smooth", "One hour:", "never smooth")
        sub = T("app 38ee9fad" if PORTRAIT else "app 38ee9fad, 60 minutes of one day", 28, SLATE)
        place(sub, left=-SX, top=hl.get_bottom()[1] - 0.22)
        stat = VGroup(T("about 15%", 44 if PORTRAIT else 54, weight="BOLD"),
                      T("noise every minute" if PORTRAIT else "minute-to-minute noise", 28)
                      ).arrange(DOWN, buff=0.08, aligned_edge=LEFT)
        if PORTRAIT:
            leg = VGroup(swatch(TEAL_LINE, "30-min median"), swatch(GOLD, "15% either side", "fill")
                         ).arrange(DOWN, buff=0.08, aligned_edge=LEFT)
            place(leg, left=-SX, bottom=TEXT_FLOOR)
            place(stat, left=-SX, bottom=leg.get_top()[1] + 0.3)
            box = Box(-SX + 0.65, stat.get_top()[1] + 0.75, SX - 0.3, sub.get_bottom()[1] - 0.45, (-1, 60), (5000, 9000))
            xt = [(0, "0"), (30, "30"), (59, "60")]
        else:
            leg = VGroup(swatch(SLATE, "each minute", "square"), swatch(TEAL_LINE, "30-minute median"),
                         swatch(GOLD, "15% either side", "fill")).arrange(DOWN, buff=0.15, aligned_edge=LEFT)
            box = Box(-SX + 0.75, -2.0, 1.0, sub.get_bottom()[1] - 0.45, (-1, 60), (5000, 9000))
            place(stat, left=1.6, top=box.y1)
            place(leg, left=1.6, top=stat.get_bottom()[1] - 0.5)
            xt = [(0, "0"), (30, "30"), (59, "60 min")]
        ax = axes(box, [(5000, "5k"), (6000, "6k"), (7000, "7k"), (8000, "8k"), (9000, "9k")], xt)
        xs = list(range(60))
        band = Polygon(*[box.p(i, m * 1.15) for i, m in zip(xs, med)],
                       *[box.p(i, m * 0.85) for i, m in reversed(list(zip(xs, med)))],
                       stroke_width=0, fill_color=GOLD, fill_opacity=0.1)
        # the band's edges carry it; a heavier fill washes the frame out (Gate V low-contrast)
        band = VGroup(band, *[DashedVMobject(box.line(xs, med * f, GOLD, 4), num_dashes=40) for f in (1.15, 0.85)])
        dots = VGroup(*[Dot(box.p(i, v), radius=0.035 if PORTRAIT else 0.05, color=SLATE) for i, v in zip(xs, load)])
        path = box.line(xs, load, SLATE, 3)
        mline = box.line(xs, med, TEAL_LINE, 7)
        first = [leg[0]] if not PORTRAIT else []
        self.P(FadeIn(hl), FadeIn(sub), FadeIn(ax), rt=0.8)
        self.P(LaggedStart(*[FadeIn(d, scale=0.5) for d in dots], lag_ratio=0.5), Create(path, rate_func=linear),
               *[FadeIn(f) for f in first], rt=0.38 * self.D)
        self.at(0.45)
        self.P(Create(mline), FadeIn(leg[-2]), rt=1.0)
        self.at(0.62)
        self.P(FadeIn(band), FadeIn(leg[-1]), FadeIn(stat), rt=1.0)
        self.end()


