# B04: bursts. Three real one-minute bursts (load divided by the trailing median), and the measured
# numbers: about 24 per app per day, 1.9 times normal, 1 minute long, 72% peak in their first minute,
# about 1 in 3 rise the minute before.
# --------------------------------------------------------------------------------------------
class B04_Bursts(Scene):
    BID, DEFAULT = "B04", 18.0

    def construct(self):
        self.begin()
        hl = headline("Bursts jump in one minute", "Bursts jump", "in one minute")
        real = E["realism"]["real"]   # noise, bursts/day, height p50, height p90, peak in first minute (%)
        third = f"1 in {round(1 / E['rise_before'])}"
        if PORTRAIT:
            rows = [(f"{real[1]:.0f}", "bursts/app/day"), (f"{real[2]:.1f}x", "normal load"), ("1 min", "long"),
                    (f"{real[4]:.0f}%", "peak in min 1"), (third, "rise before")]
            counters = VGroup(*[VGroup(T(a, 30, weight="BOLD"), T(b, 26)).arrange(RIGHT, buff=0.16, aligned_edge=DOWN)
                                for a, b in rows]).arrange(DOWN, buff=0.1, aligned_edge=LEFT)
            place(counters, left=-SX, bottom=TEXT_FLOOR)
            cap = T("3 real bursts", 28, SLATE)
            place(cap, left=-SX, top=hl.get_bottom()[1] - 0.22)
            ptop, pbot, px0, px1 = cap.get_bottom()[1] - 0.2, counters.get_top()[1] + 0.55, -SX + 0.05, SX - 0.05
        else:
            rows = [(f"about {real[1]:.0f}", "bursts per app per day"), (f"{real[2]:.1f}x", "normal load, typical burst"),
                    ("1 min", "typical length"), (f"{real[4]:.0f}%", "peak in the first minute"),
                    (third, "rise the minute before")]
            counters = VGroup(*[VGroup(T(a, 50, weight="BOLD"), T(b, 28)).arrange(DOWN, buff=0.06, aligned_edge=LEFT)
                                for a, b in rows]).arrange(DOWN, buff=0.22, aligned_edge=LEFT)
            place(counters, left=1.2, top=hl.get_bottom()[1] - 0.3)
            cap = T("3 real bursts, load / normal", 28, SLATE)
            place(cap, left=-SX, top=hl.get_bottom()[1] - 0.22)
            ptop, pbot, px0, px1 = cap.get_bottom()[1] - 0.3, -2.75, -SX + 0.05, 0.5
        n, gap = 3, 0.2
        ph = (ptop - pbot - (n - 1) * gap) / n
        panels, lines = VGroup(), VGroup()
        for i, ex in enumerate(E["burst_examples"]):
            y1 = ptop - i * (ph + gap)
            box = Box(px0, y1 - ph, px1, y1, (-10, 10), (0, 2.6))
            panels.add(DashedLine(box.p(-10, 1), box.p(10, 1), stroke_color=GREY, stroke_width=2, dash_length=0.06),
                       Line(box.p(0, 0), box.p(0, 2.6), stroke_color=GOLD, stroke_width=4))
            lines.add(box.line(list(range(-10, 11)), ex["rel"], SLATE, 6))
        last = Box(px0, pbot, px1, pbot + ph, (-10, 10), (0, 2.6))
        xl = VGroup(place(T("-10 min", 26, SLATE), left=px0, top=pbot - 0.08),
                    place(T("burst", 26, SLATE), x=last.p(0, 0)[0], top=pbot - 0.08),
                    place(T("+10", 26, SLATE), right=px1, top=pbot - 0.08))
        self.P(FadeIn(hl), FadeIn(cap), FadeIn(panels), FadeIn(xl), rt=0.7)
        self.P(LaggedStart(*[Create(l) for l in lines], lag_ratio=0.3), rt=1.6)
        for frac, c in zip((0.12, 0.27, 0.40, 0.50, 0.73), counters):
            self.at(frac)
            self.P(FadeIn(c, shift=UP * 0.1), rt=0.5)
        self.end()


