# B05: repeats. Burst start times of app 9aba8d35 over its 10 training days (one row per day), next to
# the same number of bursts at random times (a constructed comparison, seed 0).
# --------------------------------------------------------------------------------------------
class B05_Repeats(Scene):
    BID, DEFAULT = "B05", 12.0

    def construct(self):
        self.begin()
        ra = E["raster"]
        hl = headline("Bursts come back at the same time", "Bursts come back", "at the same time")
        pct = f"{100 * ra['repeat_share']:.0f}%"

        def raster(x0, y0, x1, y1, minutes, color, title, caption=None, ylab=True):
            """One panel: its own title above it, the y label beside it, a time-of-day axis under it."""
            box = Box(x0, y0, x1, y1, (0, 1440), (10.5, 0.5))
            frame = Rectangle(width=x1 - x0, height=y1 - y0, stroke_color=GREY, stroke_width=2).move_to(
                [(x0 + x1) / 2, (y0 + y1) / 2, 0])
            ttl = stack(*title, size=28 if PORTRAIT else 26, weight="BOLD", buff=0.03)
            place(ttl, left=x0, bottom=y1 + 0.12)
            parts = VGroup(frame, ttl)
            if ylab:
                parts.add(place(T("one row per day", 26, SLATE).rotate(PI / 2), right=x0 - 0.1, y=(y0 + y1) / 2))
            if PORTRAIT:   # ticks and the axis label share one line
                lo = place(T("0", 26, SLATE), left=x0, top=y0 - 0.08)
                hi = place(T("24h", 26, SLATE), right=x1, top=y0 - 0.08)
                mid = place(T("time of day", 26, SLATE), x=(lo.get_right()[0] + hi.get_left()[0]) / 2, top=y0 - 0.08)
                axis = VGroup(lo, mid, hi)
            else:
                axis = VGroup(*[place(T(lab, 26, SLATE), x=box.p(m, 0)[0], top=y0 - 0.08)
                                for m, lab in ((0, "0h"), (720, "12h"), (1440, "24h"))])
                axis.add(place(T("time of day", 26, SLATE), x=(x0 + x1) / 2, top=axis.get_bottom()[1] - 0.06))
            if caption:
                axis.add(place(T(caption, 26, SLATE), left=x0, top=axis.get_bottom()[1] - 0.08))
            parts.add(axis)
            dots = VGroup(*[Dot(box.p(m, day + 1), radius=0.035 if PORTRAIT else 0.07, color=color)
                            for m, day in zip(minutes, ra["day"])])
            return parts, dots

        if PORTRAIT:
            stat = VGroup(VGroup(T(pct, 30, weight="BOLD"), T("return within", 26)).arrange(RIGHT, buff=0.15,
                                                                                         aligned_edge=DOWN),
                          T("5 min, another day", 26)).arrange(DOWN, buff=0.06, aligned_edge=LEFT)
            place(stat, left=-SX, top=hl.get_bottom()[1] - 0.2)
            x0, x1 = -SX + 0.46, SX - 0.05
            top, bot = stat.get_bottom()[1] - 0.25, TEXT_FLOOR
            tt, ax, gap = 0.76, 0.36, 0.2           # two-line title above, axis line below, gap between panels
            h = (top - bot - 2 * (tt + ax) - gap) / 2
            a = raster(x0, top - tt - h, x1, top - tt, ra["minute"], TEAL, ("Real bursts,", "one app"), ylab=False)
            b0 = bot + ax
            b = raster(x0, b0, x1, b0 + h, ra["random_minute"], GREY, ("Same bursts,", "random times"), ylab=False)
            shared = T("one row per day", 26, SLATE).rotate(PI / 2)   # one y label for both stacked panels
            place(shared, right=x0 - 0.1, y=(top - tt + b0) / 2)
            a[0].add(shared)
        else:
            stat = VGroup(T(pct, 54, weight="BOLD"), stack("return within", "5 min, another day", size=28, buff=0.04)
                          ).arrange(RIGHT, buff=0.25)
            place(stat, left=-SX, bottom=-SY + 0.02)
            y1 = hl.get_bottom()[1] - 0.75
            y0 = stat.get_top()[1] + 1.55
            a = raster(-SX + 0.45, y0, -0.75, y1, ra["minute"], TEAL, ("Real bursts, one app",),
                       "app 9aba8d35, 10 training days")
            b = raster(0.95, y0, SX - 0.35, y1, ra["random_minute"], GREY, ("Same bursts, random times",))
        self.P(FadeIn(hl), FadeIn(a[0]), rt=0.7)
        self.P(LaggedStart(*[GrowFromCenter(d) for d in a[1]], lag_ratio=0.12), rt=2.9)
        self.at(0.38)
        self.P(FadeIn(stat, shift=UP * 0.1), rt=0.6)
        self.at(0.45)   # fully visible by about 0.57 of the beat: a hold of more than 3 s before the cut
        self.P(FadeIn(b[0]), LaggedStart(*[GrowFromCenter(d) for d in b[1]], lag_ratio=0.05), rt=1.2)
        self.end()


