# B06: what it means for autoscaling. Held-out apps, 65 unseen days (evidence/demo_stdout.txt).
# --------------------------------------------------------------------------------------------
class B06_Plans(Scene):
    BID, DEFAULT = "B06", 15.0

    def construct(self):
        self.begin()
        R = E["results"]
        hl = headline("Three ways to meet a burst", "Three ways to", "meet a burst")
        opts = [("React", "Kubernetes rule", "threshold", CRIMSON),
                ("Spare servers", "fixed for the day's peak", "fixed", SLATE),
                ("Use yesterday" if PORTRAIT else "Plan from yesterday", "same time yesterday rule", "yesterday", TEAL)]
        bl = 1.6 if PORTRAIT else 2.9           # bar length at the axis maximum (6% late / 40k server-min)
        rows = []
        for name, rule, key, col in opts:
            cost, late = R[key]
            title = Group(T(name, 30 if PORTRAIT else 34, weight="BOLD"),
                          *([logo("kubernetes", 0.36)] if key == "threshold" else [])).arrange(RIGHT, buff=0.15)
            sub = T(rule, 26, SLATE)
            bh = 0.22 if PORTRAIT else 0.28
            lbar = Rectangle(width=max(late / 6 * bl, 0.04), height=bh, stroke_width=0, fill_color=CRIMSON,
                             fill_opacity=1)
            cbar = Rectangle(width=cost / 40000 * bl, height=bh, stroke_width=0, fill_color=GREY if PORTRAIT else col,
                             fill_opacity=1)
            lval = T(f"{late:.2f}%" if PORTRAIT else f"{late:.2f}% late", 28 if not PORTRAIT else 26, weight="BOLD")
            cval = T(k(cost) if PORTRAIT else f"{k(cost)} server-min", 28 if not PORTRAIT else 26)
            rows.append((title, sub, lbar, lval, cbar, cval))
        if PORTRAIT:
            foot = T("5 held-out apps", 26, SLATE)
            key = VGroup(swatch(CRIMSON, "late requests", "square", 26), swatch(GREY, "server-min a day", "square", 26)
                         ).arrange(DOWN, buff=0.06, aligned_edge=LEFT)
            place(foot, left=-SX, top=hl.get_bottom()[1] - 0.22)
            place(key, left=-SX, top=foot.get_bottom()[1] - 0.12)
            blocks = [Group(title, Group(lbar, lval).arrange(RIGHT, buff=0.14),
                            Group(cbar, cval).arrange(RIGHT, buff=0.14)).arrange(DOWN, buff=0.04, aligned_edge=LEFT)
                      for title, sub, lbar, lval, cbar, cval in rows]
            column(blocks, key.get_bottom()[1] - 0.25, TEXT_FLOOR, left=-SX, min_gap=0.08)
            head = VGroup(foot, key)
        else:
            lx, cx = -0.9, 2.45
            head = VGroup(place(T("late requests", 28, SLATE), left=lx, top=hl.get_bottom()[1] - 0.3),
                          place(T("server-min per day", 28, SLATE), left=cx, top=hl.get_bottom()[1] - 0.3))
            names = [Group(title, sub).arrange(DOWN, buff=0.08, aligned_edge=LEFT) for title, sub, *_ in rows]
            column(names, head.get_bottom()[1] - 0.45, -2.75, left=-SX, min_gap=0.5)
            blocks = []
            for nm, (title, sub, lbar, lval, cbar, cval) in zip(names, rows):
                yy = nm.get_center()[1]
                place(lbar, left=lx, y=yy + 0.22)
                place(lval, left=lx, top=lbar.get_bottom()[1] - 0.1)
                place(cbar, left=cx, y=yy + 0.22)
                place(cval, left=cx, top=cbar.get_bottom()[1] - 0.1)
                blocks.append(Group(nm, lbar, lval, cbar, cval))
            head.add(place(T("5 held-out apps, 65 unseen days", 28, SLATE), left=-SX, bottom=-SY))
        self.P(FadeIn(hl), FadeIn(head), rt=0.7)
        for frac, g in zip((0.12, 0.32, 0.62), blocks):
            self.at(frac)
            self.P(FadeIn(g, shift=RIGHT * 0.15), rt=0.8)
        self.end()


