# --------------------------------------------------------------------------------------------
class B07_TestTraffic(Scene):
    BID, DEFAULT = "B07", 21.0

    def construct(self):
        self.begin()
        C = E["compare"]
        fit = E["realism"]["fitted"]
        hl = headline("Test traffic should look real", "Test traffic", "should look real")
        if PORTRAIT:
            labels = [("made-up, redrawn:", "5% noise, slow ramp"), ("real: about 15%", "noise, 1-min jumps"),
                      ("fitted generator:", f"noise {fit[0] * 100:.0f}%,", f"{fit[4]:.0f}% peak in min 1")]
        else:
            labels = [("made-up (redrawn): 5% noise, slow ramp",), ("real: about 15% noise, one-minute jumps",),
                      (f"fitted generator: {fit[0] * 100:.0f}% noise, {fit[4]:.0f}% peak in the first minute",)]
        spec = [("made_up", GREY), ("real", SLATE), ("fitted", TEAL)]
        top = hl.get_bottom()[1] - 0.25
        bottom = -2.95   # the last trace stays clear of the corner mark
        labs = [stack(*lab, size=26 if PORTRAIT else 28, weight="BOLD" if key == "fitted" else "NORMAL", buff=0.03)
                for (key, _), lab in zip(spec, labels)]
        th = (top - bottom - sum(l.height for l in labs) - 3 * 0.1 - 2 * 0.25) / 3
        rows, y = [], top
        for (key, col), lab in zip(spec, labs):
            place(lab, left=-SX, top=y)
            y = lab.get_bottom()[1] - 0.1
            box = Box(-SX, y - th, SX, y, (0, 1440), (0, 3.2))
            frame = Rectangle(width=2 * SX, height=th, stroke_color=GREY, stroke_width=2).move_to([0, y - th / 2, 0])
            rows.append((lab, frame, box.line(list(range(1440)), C[key], col, 2 if PORTRAIT else 2.5)))
            y = y - th - 0.25
        self.P(FadeIn(hl), FadeIn(rows[0][0]), FadeIn(rows[0][1]), rt=0.6)
        self.P(Create(rows[0][2], rate_func=linear), rt=2.2)
        self.at(0.27)
        self.P(FadeIn(rows[1][0]), FadeIn(rows[1][1]), rt=0.4)
        self.P(Create(rows[1][2], rate_func=linear), rt=2.2)
        self.at(0.52)
        self.P(FadeIn(rows[2][0]), FadeIn(rows[2][1]), rt=0.4)
        self.P(Create(rows[2][2], rate_func=linear), rt=2.2)
        self.end()


# --------------------------------------------------------------------------------------------
# B10: title restate. The full HAI mark, the title with a terracotta period, the handle, the repo.
# --------------------------------------------------------------------------------------------
class B10_Outro(Scene):
    def construct(self):
        self.camera.background_color = CREAM
        D = beat_seconds("B10", 4.0)
        mark = hai_mark(1.1 if PORTRAIT else 1.5)
        lines = ("What Real", "Cloud Traffic", "Looks Like.") if PORTRAIT else ("What Real Cloud Traffic Looks Like.",)
        title = VGroup(*[T(s, 52 if PORTRAIT else 64, INK, SERIF, t2c={".": TERRA}) for s in lines]).arrange(DOWN, buff=0.05)
        handle = T("@HumanitariansAI", 28 if PORTRAIT else 36, weight="BOLD")
        repo = (stack("github.com/", "lakshdhamija/", "rl-autoscaler", size=26, color=SLATE, buff=0.05, aligned=ORIGIN)
                if PORTRAIT else T("github.com/lakshdhamija/rl-autoscaler", 28, SLATE))
        g = VGroup(mark, title, handle, repo).arrange(DOWN, buff=0.28 if PORTRAIT else 0.45).move_to(ORIGIN)
        if PORTRAIT:
            place(g, top=SY - 0.2)
        rule = Line(LEFT, RIGHT, stroke_color=GOLD, stroke_width=8).set_width(min(title.width, 2 * SX))
        rule.move_to([0, (title.get_bottom()[1] + handle.get_top()[1]) / 2, 0])
        self.play(FadeIn(mark, shift=UP * 0.1), FadeIn(title), run_time=0.6)
        self.play(Create(rule), FadeIn(handle), FadeIn(repo), run_time=0.4)
        self.wait(max(D - 1.0, 0.1))
